        AND gdpg.gb_DPG_pur_user_id = #{purUserId}



        AND gdpg.gb_DPG_pay_type = #{payType}


        AND gdpg.gb_DPG_status < #{purStatus}


        AND gdpg.gb_DPG_status = #{purGoodsEqualStatus}


        AND gdpg.gb_dpg_purchase_week = #{week}


        AND gdpg.gb_DPG_stock_finish_date = #{date}


        AND gdpg.gb_DPG_dis_goods_id = #{disGoodsId}


        AND gdpg.gb_DPG_dis_goods_father_id = #{disGoodsFatherId}


        AND gdpg.gb_DPG_dis_goods_grand_id = #{disGoodsGrandId}


        AND gdpg.gb_DPG_dis_goods_great_id = #{disGoodsGreatId}


        AND gdpg.gb_DPG_stock_finish_date >= #{startDate}


        AND gdpg.gb_DPG_stock_finish_date <= #{stopDate}


        AND gdpg.gb_DPG_stock_finish_date = #{finishDate}


        AND gdpg.gb_DPG_purchase_nx_supplier_id = #{supplierId}


        AND gdpg.gb_DPG_purchase_nx_supplier_id = #{supplierBuy}


        AND gdpg.gb_DPG_purchase_nx_supplier_id != -1


        AND gdpg.gb_DPG_status > #{dayuStatus}


        AND gdpg.gb_DPG_purchase_type != #{typeNotEqual}


        AND gdpg.gb_DPG_batch_id = #{batchId}


GROUP BY gdpg.gb_DPG_dis_goods_id, dg.gb_dg_goods_name


        ORDER BY gb_dg_selling_price DESC, buy_count DESC, dg.gb_distributer_goods_id ASC


        ORDER BY buy_count DESC, gb_dg_selling_price DESC, dg.gb_distributer_goods_id ASC


        ORDER BY gb_dg_selling_price DESC, buy_count DESC, dg.gb_distributer_goods_id ASC



    LIMIT #{offset}, #{limit}

SELECT g.gb_dg_goods_name, g.gb_dg_goods_standardname, g.gb_dg_nx_father_img, t.goods_id AS gb_distributer_goods_id, t.times AS gb_dg_quantity_days FROM ( SELECT gb_DPG_dis_goods_id AS goods_id, COUNT(*) AS times FROM gb_distributer_purchase_goods WHERE gb_DPG_stock_finish_date BETWEEN #{startDate} AND #{stopDate} AND gb_DPG_distributer_id = #{disId} AND gb_DPG_status > 2 AND gb_DPG_buy_subtotal > 0
AND gb_DPG_purchase_type != #{typeNotEqual}
GROUP BY gb_DPG_dis_goods_id ) t JOIN gb_distributer_goods g ON g.gb_distributer_goods_id = t.goods_id ORDER BY t.times DESC LIMIT 10

SELECT g.gb_dg_goods_name, g.gb_dg_goods_standardname, g.gb_dg_nx_father_img, t.goods_id AS gb_distributer_goods_id, t.total_subtotal AS goodsPurTotalSubtotal FROM ( SELECT gb_DPG_dis_goods_id AS goods_id, ROUND(SUM(gb_DPG_buy_subtotal), 1) AS total_subtotal FROM gb_distributer_purchase_goods WHERE gb_DPG_stock_finish_date BETWEEN #{startDate} AND #{stopDate} AND gb_DPG_distributer_id = #{disId} AND gb_DPG_status > 2 AND gb_DPG_buy_subtotal > 0
AND gb_DPG_purchase_type != #{typeNotEqual}
GROUP BY gb_DPG_dis_goods_id ) t JOIN gb_distributer_goods g ON g.gb_distributer_goods_id = t.goods_id ORDER BY t.total_subtotal DESC LIMIT 10

SELECT g.gb_dg_goods_name, g.gb_dg_goods_standardname, g.gb_dg_nx_father_img, t.goods_id AS gb_distributer_goods_id, t.max_price AS gbDgGoodsHighestPrice, t.min_price AS gbDgGoodsLowestPrice, t.price_diff AS goodsPriceDiff, t.price_fluctuation AS goodsPriceFluctuation FROM ( SELECT gb_DPG_dis_goods_id AS goods_id, MAX(CAST(gb_DPG_buy_price AS DECIMAL(10, 1))) AS max_price, MIN(CAST(gb_DPG_buy_price AS DECIMAL(10, 1))) AS min_price, ROUND((MAX(CAST(gb_DPG_buy_price AS DECIMAL(10, 1))) - MIN(CAST(gb_DPG_buy_price AS DECIMAL(10, 1)))), 1) AS price_diff, ROUND(((MAX(CAST(gb_DPG_buy_price AS DECIMAL(10, 1))) - MIN(CAST(gb_DPG_buy_price AS DECIMAL(10, 1)))) / NULLIF(MIN(CAST(gb_DPG_buy_price AS DECIMAL(10, 1))), 0)) * 100, 1) AS price_fluctuation FROM gb_distributer_purchase_goods WHERE gb_DPG_stock_finish_date BETWEEN #{startDate} AND #{stopDate} AND gb_DPG_distributer_id = #{disId} AND gb_DPG_buy_price IS NOT NULL AND gb_DPG_status > 2
AND gb_DPG_purchase_type != #{typeNotEqual}
GROUP BY gb_DPG_dis_goods_id ) t JOIN gb_distributer_goods g ON g.gb_distributer_goods_id = t.goods_id ORDER BY t.price_fluctuation DESC LIMIT 10

